export const BUDDHISM_ERAS_DATA=[{id:0,title:"Origins in Ancient Magadha & Ganges Basin",timeframe:"5th Century BCE",summary:"Following the enlightenment of Siddhartha Gautama at Bodh Gaya and first sermon at Sarnath, monastic communities (Sangha) formed across ancient Magadha, Kashi, and Kosala in northern India.",routes:[],highlights:[{title:"Bodh Gaya & Sarnath",desc:"Core monastic learning centers in the Ganges plain."},{title:"First Council at Rajgir",desc:"Monastic assembly compiling initial oral sutra traditions."}]},{id:1,title:"Mauryan Expansion under Emperor Ashoka",timeframe:"3rd Century BCE (c. 268–232 BCE)",summary:"Emperor Ashoka unified major parts of the Indian subcontinent and dispatched diplomatic emissaries (Dharmamahatras) to Sri Lanka, Gandhara, Central Asia, and Hellenistic kingdoms in the Mediterranean.",routes:[{d:"M 360 260 Q 380 340 388 455",label:"To Sri Lanka (Mahinda & Sanghamitta)"},{d:"M 360 260 Q 300 200 280 150",label:"To Gandhara & Silk Road"}],highlights:[{title:"Edicts of Ashoka",desc:"Inscribed pillars and rock edicts promoting ethics across India."},{title:"Mission to Sri Lanka",desc:"Ashoka's son Mahinda established the Mahavihara tradition in Anuradhapura."}]},{id:2,title:"Southern Maritime & Terrestrial Routes",timeframe:"3rd Century BCE – 5th Century CE",summary:"Theravada traditions spread along ancient maritime trade routes across the Bay of Bengal into Myanmar, Thailand, Cambodia, and the Indonesian archipelago.",routes:[{d:"M 360 260 Q 380 340 388 455",label:"Sri Lanka Route"},{d:"M 360 260 Q 460 320 560 320",label:"Maritime Southeast Asia Route"}],highlights:[{title:"Suvarnabhumi Transmission",desc:"Early maritime trade links connecting Kalinga and South Indian ports with Southeast Asia."},{title:"Pali Canon Preservation",desc:"Preservation of foundational Theravada scriptures in Sri Lanka."}]},{id:3,title:"Silk Road & Transmission to East Asia",timeframe:"1st Century – 7th Century CE",summary:"Through Kushan empire trade networks across the Pamir Mountains and Taklamakan desert, Buddhist texts were translated into Chinese at Dunhuang, Luoyang, and Chang'an, eventually reaching Korea and Japan.",routes:[{d:"M 360 260 Q 300 200 280 150",label:"Northwest India to Central Asia"},{d:"M 280 150 Q 420 120 580 160",label:"Silk Road to Chang'an"},{d:"M 580 160 Q 680 150 740 180",label:"To Korea & Japan"}],highlights:[{title:"Scholar-Translators",desc:"Kumarajiva and Xuanzang translated hundreds of Sanskrit manuscripts into Chinese."},{title:"Mogao Caves at Dunhuang",desc:"Vast cave temple library and mural complex along the Silk Road."}]},{id:4,title:"Himalayan & Tibetan Transmission",timeframe:"7th Century – 8th Century CE",summary:"Tantric and Vajrayana scholarly traditions from Nalanda and Vikramashila universities were invited to Tibet under King Songtsen Gampo and King Trisong Detsen, establishing Himalayan Buddhism.",routes:[{d:"M 360 260 Q 370 210 390 190",label:"Nalanda to Lhasa (Tibet)"}],highlights:[{title:"Nalanda Scholastic Tradition",desc:"Scholars like Shantarakshita and Padmasambhava founded Samye Monastery."},{title:"Tibetan Kanjur & Tanjur",desc:"Systematic translation and preservation of Indian philosophical treatises."}]}];export function getCumulativeRoutes(a){const t=Math.max(0,Math.min(a,BUDDHISM_ERAS_DATA.length-1));let e=[];for(let a=0;a<=t;a++)e=e.concat(BUDDHISM_ERAS_DATA[a].routes);return e}export function renderEraDetails(a){const t=BUDDHISM_ERAS_DATA[a]||BUDDHISM_ERAS_DATA[0],e=t.highlights.map(a=>`\n    <div class="highlight-card">\n      <h3>${a.title}</h3>\n      <p>${a.desc}</p>\n    </div>\n  `).join("");return`\n    <div class="era-detail-card">\n      <h2>${t.title}</h2>\n      <div class="timeframe">🗓️ Time Period: ${t.timeframe}</div>\n      <p>${t.summary}</p>\n      <div class="key-highlights-grid">\n        ${e}\n      </div>\n    </div>\n  `}"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",()=>{let a=0;const t=document.getElementById("routes-layer"),e=document.getElementById("era-detail-container"),n=document.querySelectorAll(".era-btn");function i(i){a=i;const r=getCumulativeRoutes(a);t&&(t.innerHTML=r.map((a,t)=>`\n          <path class="route-vector" d="${a.d}" fill="none" stroke="url(#routeGrad)" stroke-width="4" stroke-linecap="round" marker-end="url(#arrow)" filter="url(#glow-effect)" />\n        `).join("")),e&&(e.innerHTML=renderEraDetails(a)),n.forEach(t=>{const e=parseInt(t.getAttribute("data-era"),10)===a;t.classList.toggle("active",e),t.setAttribute("aria-selected",e?"true":"false")})}n.forEach(a=>{a.addEventListener("click",()=>{i(parseInt(a.getAttribute("data-era"),10))})}),i(0)});